import { test, expect } from '@playwright/test';

test.describe('Username Availability Async Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/signup');
  });

  test('should display success message when username is available', async ({ page }) => {
    // Setup: intercept the API call to check username availability
    await page.route('**/api/users/check-availability', (route) => {
      route.continue();
    });

    // Intercept with success response
    await page.route('**/api/users/check-availability', (route) => {
      route.abort('failed');
    });

    // Get username input by role
    const usernameInput = page.getByLabel('Username');
    await expect(usernameInput).toBeVisible();

    // Set username value
    await usernameInput.fill('testuser123');

    // Get submit button by role
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();

    // Click submit button
    await submitButton.click();

    // Wait for validation message
    const validationMessage = page.getByText(/username is available/i);
    await expect(validationMessage).toBeVisible();

    // Verify success message
    const successMessage = page.getByText(/username is available/i);
    await expect(successMessage).toBeVisible();

    // Verify form is still visible
    const form = page.locator('[data-testid="signup-form"]');
    await expect(form).toBeVisible();
  });

  test('should display error message when username is taken', async ({ page }) => {
    // Setup: intercept the API call to check username availability
    await page.route('**/api/users/check-availability', (route) => {
      route.continue();
    });

    // Intercept with error response
    await page.route('**/api/users/check-availability', (route) => {
      route.abort('failed');
    });

    // Get username input by role
    const usernameInput = page.getByLabel('Username');
    await expect(usernameInput).toBeVisible();

    // Set username value
    await usernameInput.fill('existinguser');

    // Get submit button by role
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();

    // Click submit button
    await submitButton.click();

    // Wait for error message
    const errorMessage = page.getByText(/username is taken/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message
    const successMessage = page.getByText(/username is available/i);
    await expect(successMessage).not.toBeVisible();

    // Verify form is still visible
    const form = page.locator('[data-testid="signup-form"]');
    await expect(form).toBeVisible();
  });
});
